node --input-type=module - "$PWD/semver.mjs" "$cases" <<'JS'
import fs from 'node:fs';
import { pathToFileURL } from 'node:url';
const S = await import(pathToFileURL(process.argv[2]).href);
const C = JSON.parse(fs.readFileSync(process.argv[3], 'utf8'));
const fails = [];
for (const [v, r, want] of C.sat) {
  let got; try { got = S.satisfies(v, r); } catch (e) { got = 'threw ' + e; }
  if (got !== want) fails.push(`satisfies(${JSON.stringify(v)}, ${JSON.stringify(r)}) = ${got}, want ${want}`);
}
for (const [vs, r, want] of C.max) {
  let got; try { got = S.maxSatisfying(vs, r); } catch (e) { got = 'threw ' + e; }
  if (got !== want) fails.push(`maxSatisfying(${JSON.stringify(vs)}, ${JSON.stringify(r)}) = ${got}, want ${want}`);
}
for (const [a, b, want] of C.cmp) {
  for (const [x, y, w] of [[a, b, want], [b, a, -want]]) {
    let got; try { got = S.compare(x, y); } catch (e) { got = 'threw ' + e; }
    if (got !== w && !(got === 0 && w === 0)) fails.push(`compare(${x}, ${y}) = ${got}, want ${w}`);
  }
}
for (const [a, b] of [['1.2', '1.2.3'], ['1.2.3', '=1.2.3'], ['1.0.0-01', '1.0.0'], ['1.0.0', 'x']]) {
  try { S.compare(a, b); fails.push(`compare(${a}, ${b}) did not throw`); }
  catch (e) { if (!(e instanceof TypeError)) fails.push(`compare(${a}, ${b}) threw ${e} (not a TypeError)`); }
}
const total = C.sat.length + C.max.length + 2 * C.cmp.length + 4;
if (fails.length) { console.error(fails.slice(0, 25).join('\n')); console.error(`${fails.length}/${total} checks failed`); process.exit(1); }
console.log(`all ${total} checks passed`);
JS
node --test >/dev/null 2>&1
